import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# Define the custom CUDA kernel for element-wise multiplication (A * s)
elementwise_mul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_mul_kernel(const float* a, const float* scalar, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] * static_cast<float>(scalar);
    }
}

torch::Tensor elementwise_mul_cuda(torch::Tensor a, float s) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_mul_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), s.to_float().data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_mul_cpp_source = (
    "torch::Tensor elementwise_mul_cuda(torch::Tensor a, float s);"
)

# Compile the inline CUDA code for matrix-scalar multiplication
elementwise_mul = load_inline(
    name="elementwise_mul",
    cpp_sources=elementwise_mul_cpp_source,
    cuda_sources=elementwise_mul_source,
    functions=["elementwise_mul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_mul = elementwise_mul

    def forward(self, A: torch.Tensor, s: float) -> torch.Tensor:
        """
        Performs matrix-scalar multiplication (C = A * s).

        Args:
            A: Input matrix of shape (M, N)
            s: Scalar value

        Returns:
            C: Resulting matrix of shape (M, N)
        """
        return self.elementwise_mul.elementwise_mul_cuda(A, s)


